import java.util.Scanner;

public class Main {

    public static int computeGCD(int a, int b) {
        int gcd_candidate = Math.max(a, b);
        while (true) {
            if (a % gcd_candidate == 0 && b % gcd_candidate == 0)
                return gcd_candidate;
            gcd_candidate--;
        }
    }

    public static void calculateDifference(double x, double y, double a, double b, double[] result) {
        result[0] = Math.abs(x * b - y * a);
        result[1] = y * b;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        double n = sc.nextDouble();

        if (n > y) {
            int g = computeGCD((int) x, (int) y);
            if (g != 1) {
                x /= g;
                y /= g;
            }
            System.out.println(x + "/" + y);
            sc.close();
            return;
        }

        double min_ratio = 1e9;
        int best_a = 0, best_b = 0;

        for (double b = n; b >= 1; b--) {
            double a = (x * b) / y;
            if (Math.floor(a) == a) {
                best_a = (int) a;
                best_b = (int) b;
                break;
            } else {
                double[] diff = new double[2];

                // Check floor(a)
                calculateDifference(x, y, Math.floor(a), b, diff);
                double ratio = diff[0] / diff[1];
                if (ratio < min_ratio) {
                    min_ratio = ratio;
                    best_a = (int) Math.floor(a);
                    best_b = (int) b;
                } else if (ratio == min_ratio && Math.floor(a) < best_a) {
                    best_a = (int) Math.floor(a);
                    best_b = (int) b;
                }

                // Check ceil(a)
                calculateDifference(x, y, Math.ceil(a), b, diff);
                ratio = diff[0] / diff[1];
                if (ratio < min_ratio) {
                    min_ratio = ratio;
                    best_a = (int) Math.ceil(a);
                    best_b = (int) b;
                } else if (ratio == min_ratio && Math.ceil(a) < best_a) {
                    best_a = (int) Math.ceil(a);
                    best_b = (int) b;
                }
            }
        }

        int g = computeGCD(best_a, best_b);
        if (g != 1) {
            best_a /= g;
            best_b /= g;
        }
        System.out.println(best_a + "/" + best_b);
        sc.close();
    }
}
